			docNamespace: "namespace1",
			cliNamespace: "namespace2",
			wantError:    true,
		},
	}

	for _, tc := range tests {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {

			var (
				creator  = &mockCreator{}
				importer = NewImporter(creator, WithNamespace(tc.cliNamespace))
